@php($latestEdit = $order->editRequests->first())
@if($latestEdit && $latestEdit->status === \App\Models\OrderEditRequest::STATUS_PENDING_FARMER)
    <div class="alert alert-warning border-0 shadow-sm"><strong>Change request sent.</strong> The order stays as-is until the farmer responds.</div>
@elseif($latestEdit && $latestEdit->status === \App\Models\OrderEditRequest::STATUS_FARMER_DENIED)
    <div class="card card-custom border-warning shadow-sm mb-4"><div class="card-body"><h5 class="fw-bold">The farmer declined your proposed changes</h5><p class="mb-3">{{ $latestEdit->farmer_response ?: 'Your original order has not been changed.' }} Choose what you want to do next.</p><div class="d-flex flex-wrap gap-2"><form method="POST" action="{{ route('customer.orders.editProposals.decision',[$order->id,$latestEdit->id]) }}">@csrf<input type="hidden" name="decision" value="proceed"><button class="btn btn-success">Proceed with original order</button></form><form method="POST" action="{{ route('customer.orders.editProposals.decision',[$order->id,$latestEdit->id]) }}" onsubmit="return confirm('Cancel this order? Reserved stock will be released.')">@csrf<input type="hidden" name="decision" value="cancel"><button class="btn btn-outline-danger">Cancel order</button></form></div></div></div>
@elseif($latestEdit && $latestEdit->status === \App\Models\OrderEditRequest::STATUS_FARMER_ACCEPTED)
    <div class="alert alert-success border-0"><strong>Changes approved.</strong> The farmer accepted your update and the order below reflects the approved quantities.</div>
@elseif($latestEdit && $latestEdit->status === \App\Models\OrderEditRequest::STATUS_CUSTOMER_PROCEEDED)
    <div class="alert alert-info border-0">You chose to proceed with the original order after the farmer declined your proposal.</div>
@endif

@if($order->canBeEditedByCustomer() && (!$latestEdit || !in_array($latestEdit->status,[\App\Models\OrderEditRequest::STATUS_PENDING_FARMER,\App\Models\OrderEditRequest::STATUS_FARMER_DENIED],true)))
    <div class="card card-custom border-0 shadow-sm mb-4"><div class="card-body p-4"><h5 class="fw-bold">Request changes to this order</h5><p class="text-muted small">Send updated quantities or order notes to the farmer. Changes apply only if the farmer accepts. You can submit requests until {{ $order->customerEditDeadline()->format('M d, Y g:i A') }} (24 hours before pickup). Set a quantity to 0 to remove that item; new products cannot be added.</p><form method="POST" action="{{ route('customer.orders.editProposals.store',$order->id) }}">@csrf<div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Product</th><th>Current quantity</th><th>Proposed quantity</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}</td><td>{{ $item->quantity }} {{ $item->unit }}</td><td><input class="form-control form-control-sm" type="number" min="0" max="10000" name="items[{{ $item->id }}]" value="{{ old('items.'.$item->id,$item->quantity) }}" required style="max-width:130px"></td></tr>@endforeach</tbody></table></div><label class="form-label" for="proposed-notes-{{ $order->id }}">Order notes</label><textarea class="form-control mb-3" id="proposed-notes-{{ $order->id }}" name="proposed_notes" rows="2" maxlength="2000">{{ old('proposed_notes',$order->notes) }}</textarea><button class="btn btn-outline-success">Send changes to farmer</button></form></div></div>
@elseif(!$order->canBeEditedByCustomer() && in_array($order->status,[\App\Models\Order::STATUS_PENDING,\App\Models\Order::STATUS_ACCEPTED,\App\Models\Order::STATUS_READY],true))
    <div class="alert alert-secondary border-0">Order changes close 24 hours before pickup. The edit deadline was {{ $order->customerEditDeadline()->format('M d, Y g:i A') }}.</div>
@endif